<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import PageHeader from '@/components/common/PageHeader.vue'
import EmptyState from '@/components/common/EmptyState.vue'
import { Button } from '@/components/ui/button'
import { api } from '@/lib/api'
import { useGovernanceStore } from '@/stores/governance'
import type { GovernanceEvent } from '@/types'
const governance = useGovernanceStore()
const audit = ref<GovernanceEvent[]>([])
const auditError = ref('')
const auditLoading = ref(false)
let generation = 0
async function loadAudit() { const id = governance.activeProjectId; const request = ++generation; audit.value = []; auditError.value = ''; if (!id) return; auditLoading.value = true; try { const data = await api.audit({ projectId: id, limit: 5 }); if (request === generation) audit.value = data.items } catch (error) { if (request === generation) auditError.value = error instanceof Error ? error.message : '审计记录加载失败' } finally { if (request === generation) auditLoading.value = false } }
watch(() => governance.activeProjectId, () => void loadAudit(), { immediate: true })
const stats = computed(() => [ { label: '当前版本', value: governance.activeProject?.currentVersion == null ? '尚未发布' : `v${governance.activeProject.currentVersion}` }, { label: '已发布规则', value: String(governance.policy?.candidate.rules.length ?? 0) }, { label: '待审提案', value: String(governance.proposals.filter(p => p.status === 'pending').length) }, { label: '历史版本', value: String(governance.versions.length) } ])
</script>
<template><div class="page"><PageHeader title="治理总览" description="查看当前项目的发布状态、提案和治理审计。"/><div class="mb-5 rounded-md border border-border bg-surface px-4 py-3 text-xs leading-relaxed text-muted-foreground"><strong class="text-foreground">运行边界：</strong>Stage A 为 log-only；治理发布不改变运行时配置，不授权工具执行。同 UID 访问并非可信隔离。</div><div v-if="governance.error" class="mb-4 rounded-md border border-destructive/30 p-3 text-sm text-destructive" role="alert">{{ governance.error }} <button class="ml-2 underline" @click="governance.initialize()">重试</button></div><div v-if="governance.loading" class="py-8 text-sm text-muted-foreground" role="status">正在加载治理数据…</div><EmptyState v-else-if="!governance.activeProject" title="尚未选择项目" description="请在侧栏创建或选择项目。新项目不会自动发布策略。"/><template v-else><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><article v-for="stat in stats" :key="stat.label" class="panel p-4"><p class="eyebrow">{{ stat.label }}</p><p class="mt-4 text-2xl font-semibold tabular">{{ stat.value }}</p></article></div><div class="mt-4 grid gap-4 lg:grid-cols-3"><section class="panel lg:col-span-2"><div class="panel-header"><div><h2 class="panel-title">最近治理审计</h2><p class="panel-kicker">实际项目状态变更</p></div><RouterLink to="/audit" class="text-xs text-muted-foreground hover:text-foreground">查看全部 →</RouterLink></div><p v-if="auditLoading" class="p-4 text-xs text-muted-foreground">加载中…</p><div v-else-if="auditError" class="p-4 text-xs text-destructive">{{ auditError }} <button class="underline" @click="loadAudit">重试</button></div><p v-else-if="!audit.length" class="p-6 text-center text-xs text-muted-foreground">暂无审计记录。</p><table v-else class="data-table"><thead><tr><th>事件</th><th>操作者</th><th>时间</th></tr></thead><tbody><tr v-for="event in audit" :key="event.id"><td>{{ event.kind }}</td><td>{{ event.actor.role }}</td><td class="tabular">{{ new Date(event.createdAt).toLocaleString('zh-CN') }}</td></tr></tbody></table></section><section class="panel"><div class="panel-header"><h2 class="panel-title">项目与连接</h2></div><dl class="space-y-4 p-4 text-xs"><div><dt class="text-muted-foreground">项目</dt><dd class="mt-1 font-medium">{{ governance.activeProject.name }}</dd></div><div><dt class="text-muted-foreground">工作区 · 创建后不可变</dt><dd class="mt-1 break-all">{{ governance.activeProject.workspace }}</dd></div><div><dt class="text-muted-foreground">治理服务状态</dt><dd class="mt-1">{{ governance.status ? '已连接 · log-only' : '状态不可用' }}</dd></div></dl><div class="border-t border-border p-4"><Button as-child variant="outline" size="sm"><RouterLink to="/editor">编辑候选策略</RouterLink></Button></div></section></div></template></div></template>
